{"checks": [{"name": "block_cancel_before_rebooking", "code": "def _is_affirmative(text):
    t = text.strip().lower()
    if len(t) > 80:
        return False
    for p in ['.', ',', '!', '?', ';', ':']:
        t = t.replace(p, ' ')
    t = ' ' + ' '.join(t.split()) + ' '
    affirmatives = [' yes ', ' yeah ', ' yep ', ' yup ', ' sure ', ' ok ', ' okay ', ' go ahead ', ' proceed ', ' do it ', ' do that ', ' do so ', ' please do ', ' sounds good ', ' that works ', ' i confirm ', ' confirm ', ' affirmative ', ' correct ', ' fine ', ' that is fine ', ' okay with me ', ' i agree ', ' agreed ', ' definitely ', ' absolutely ', ' certainly ', ' of course ', ' go for it ', ' continue ']
    return any(a in t for a in affirmatives)

def _explicit_cancel(text):
    t = text.lower()
    negations = ['do not cancel', 'not cancel', 'no cancel', 'do not want to cancel']
    if any(n in t for n in negations):
        return False
    phrases = [
        'go ahead and cancel', 'go ahead cancel', 'please cancel', 'can you cancel', 'could you cancel', 'would you cancel',
        'i want to cancel', 'i would like to cancel', 'lets cancel', 'yes cancel', 'yeah cancel', 'okay cancel', 'ok cancel',
        'cancel it', 'cancel the reservation', 'cancel my reservation', 'cancel this reservation', 'cancel the booking', 'cancel my booking',
        'cancel the flight', 'cancel my flight', 'cancel the trip', 'cancel the itinerary', 'cancel the ticket', 'cancel the pnr', 'cancel pnr',
        'cancel reservation', 'cancel booking', 'cancel flight', 'proceed with cancel', 'proceed with the cancel', 'proceed with cancellation',
        'proceed with the cancellation', 'do the cancellation', 'make the cancellation', 'initiate cancellation', 'go ahead with cancellation',
        'go ahead with the cancellation', 'go ahead with cancel', 'go ahead with the cancel', 'cancel now', 'cancel as soon as possible', 'cancel asap',
        'confirm cancellation', 'confirm the cancellation', 'i confirm cancel', 'confirm cancel', 'i authorize', 'authorize cancellation',
        'you can cancel', 'you may cancel', 'cancel for me', 'cancel my itinerary', 'cancel the tickets', 'cancel my tickets', 'cancel the seats',
        'cancel my seats'
    ]
    return any(p in t for p in phrases)

def check(call, history):
    if call.get('name') != 'cancel_reservation':
        return False
    for msg in history:
        if msg.get('role') == 'assistant':
            for tc in msg.get('tool_calls', []) or []:
                if tc.get('name') == 'book_reservation':
                    return False

    recent = history[-20:] if len(history) > 20 else history
    last_user = None
    last_user_idx = -1
    for i in range(len(recent)-1, -1, -1):
        if recent[i].get('role') == 'user':
            last_user = recent[i]
            last_user_idx = i
            break
    if last_user:
        last_user_text = (last_user.get('content') or '')
        if _is_affirmative(last_user_text):
            for j in range(last_user_idx-1, -1, -1):
                if recent[j].get('role') == 'assistant':
                    if 'cancel' in (recent[j].get('content') or '').lower():
                        return False
                    break

    recent_users = [m for m in history if m.get('role') == 'user']
    for msg in reversed(recent_users[-10:]):
        text = (msg.get('content') or '').lower()
        if not text:
            continue
        if any(neg in text for neg in ['do not cancel', 'not cancel', 'no cancellation', 'do not want to cancel']):
            continue
        has_cancel = 'cancel' in text
        has_book = any(w in text for w in ['book', 'rebook', 'new reservation', 'new booking', 'change reservation', 'change flight', 'change the flight', 'change my flight'])
        if has_cancel and has_book:
            if _explicit_cancel(text):
                return False
            return True
        if has_cancel or has_book:
            return False
    return False"}]}

{"checks":[{"name":"block_transfer_with_pending_in_scope_actions","code":"def check(call, history):
    import re, json
    if call.get('name') != 'transfer_to_human_agents':
        return False

    def parse_args(a):
        if isinstance(a, str):
            try:
                return json.loads(a)
            except Exception:
                return {}
        return a if isinstance(a, dict) else {}

    args = parse_args(call.get('arguments', {}))
    summary = str(args.get('summary') or '')
    refusal_re = re.compile(r"(not able|unable|cannot|can't|can not|won't be able|not allowed|not eligible|does not meet|doesn't meet|not meet|no refund|not within|outside|not possible|not permitted|not covered|requires? insurance|not qualify|does not qualify)", re.I)
    if summary and refusal_re.search(summary):
        return False

    action_words = ['cancel', 'upgrade', 'change', 'book', 'rebook', 'modify']
    executed = set()
    for msg in history:
        if msg.get('role') == 'assistant':
            for tc in msg.get('tool_calls', []) or []:
                if tc.get('name') == 'transfer_to_human_agents':
                    continue
                a = parse_args(tc.get('arguments', {}))
                rid = a.get('reservation_id')
                if rid:
                    executed.add(str(rid))

    recent = history[-20:]
    neg_re = re.compile(r"(not able|unable|cannot|can't|can not|won't|will not|not going to|not allowed|not eligible|doesn't meet|does not meet|not meet|no refund|not within|outside|not possible|not permitted|not covered|requires? insurance|not qualify|does not qualify)", re.I)
    plan_re = re.compile(r"((i|we)[ ]*('ll|will|can|could|would|shall|'m|am|'re|are)[^.!?;,]{0,100}(cancel|cancellation|upgrade|change|book|booking|rebook|rebooking|modify|modification)|let me[^.!?;,]{0,80}(cancel|cancellation|upgrade|change|book|booking|rebook|rebooking|modify|modification)|(do you want|would you like)[^.!?;,]{0,80}(me to|to)[^.!?;,]{0,80}(cancel|cancellation|upgrade|change|book|booking|rebook|rebooking|modify|modification)|please[ ]+confirm[^.!?;,]{0,100}(cancel|cancellation|upgrade|change|book|booking|rebook|rebooking|modify|modification|reservation|booking)|(proceed|go ahead)[^.!?;,]{0,100}(with|and)?[^.!?;,]{0,100}(cancel|cancellation|upgrade|change|book|booking|rebook|rebooking|modify|modification|reservation|booking)|(i|we)[ ]*(have|'ve|already)[ ]+(cancelled|canceled|upgraded|changed|booked|rebooked|modified))", re.I)

    def get_ids(text):
        return set(re.findall(r'(?<![A-Z0-9])[A-Z0-9]{6}(?![A-Z0-9])', text))

    def is_planned(text):
        for clause in re.split(r'[.!?;,]', text):
            if not clause.strip() or neg_re.search(clause):
                continue
            if plan_re.search(clause):
                return True
        return False

    for i, msg in enumerate(recent):
        if msg.get('role') != 'user':
            continue
        text = msg.get('content') or ''
        lower = text.lower()
        if not any(w in lower for w in action_words):
            continue
        ids = get_ids(text)
        planned = False
        for j in range(i+1, min(len(recent), i+8)):
            m = recent[j]
            if m.get('role') == 'assistant':
                c = m.get('content') or ''
                if is_planned(c):
                    planned = True
                    ids.update(get_ids(c))
                tcs = m.get('tool_calls', []) or []
                if any(tc.get('name') == 'transfer_to_human_agents' for tc in tcs):
                    break
        if planned:
            for rid in ids:
                if rid not in executed:
                    return True

    refused_ids = set()
    for m in recent:
        if m.get('role') == 'assistant':
            c = m.get('content') or ''
            if refusal_re.search(c):
                refused_ids.update(get_ids(c))

    sl = summary.lower()
    if summary and any(w in sl for w in action_words):
        if re.search(r"(request|want|ask|need)", sl):
            ids = get_ids(summary)
            for rid in ids:
                if rid not in executed and rid not in refused_ids:
                    return True
    return False"}]}

{"checks":[{"name":"block_extra_checked_bags","code":"import re

def check(call, history):
    if call.get('name') != 'book_reservation':
        return False
    args = call.get('arguments', {})
    total = args.get('total_baggages')
    if not isinstance(total, int) or total <= 0:
        return False
    user_text = ' '.join((m.get('content') or '').lower() for m in history if m.get('role') == 'user')
    if 'bag' not in user_text and 'baggage' not in user_text:
        return True
    no_bag_patterns = [
        r'\bno\s+(?:checked\s+)?bags?\b',
        r'\bzero\s+(?:checked\s+)?bags?\b',
        r'\b0\s+(?:checked\s+)?bags?\b',
        r'\bwithout\s+(?:any\s+)?(?:checked\s+)?bags?\b',
        r'\bnone\s+(?:checked\s+)?bags?\b',
        r'\bno\s+checked\s+baggage\b',
        r'\bzero\s+checked\s+baggage\b',
        r'\bwithout\s+(?:any\s+)?checked\s+baggage\b',
    ]
    for pat in no_bag_patterns:
        if re.search(pat, user_text):
            return True
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'a': 1, 'an': 1
    }
    counts = []
    pattern1 = r'\b(\d+|zero|one|two|three|four|five|six|seven|eight|nine|ten|a|an)\s+(?:checked\s+)?bags?\b'
    for m in re.finditer(pattern1, user_text):
        val = m.group(1)
        if val.isdigit():
            counts.append(int(val))
        else:
            counts.append(word_to_num.get(val, 0))
    pattern2 = r'\b(?:checked\s+)?bags?\s*(?:are|is|:)?\s*(\d+|zero|one|two|three|four|five|six|seven|eight|nine|ten|a|an)\b'
    for m in re.finditer(pattern2, user_text):
        val = m.group(1)
        if val.isdigit():
            counts.append(int(val))
        else:
            counts.append(word_to_num.get(val, 0))
    if not counts:
        return False
    num_passengers = len(args.get('passengers') or [])
    if num_passengers < 1:
        num_passengers = 1
    per_person = any(phrase in user_text for phrase in ['each', 'per person', 'per passenger', 'per traveler'])
    requested_total = 0
    for c in counts:
        if per_person:
            requested_total += c * num_passengers
        else:
            requested_total += c
    return total > requested_total"}]}

{"checks":[{"name":"block_non_cheapest_itinerary","code":"import re

def check(call, history):
    name = call.get('name')
    if name not in ('update_reservation_flights', 'book_reservation'):
        return False
    flights = call.get('arguments', {}).get('flights', [])
    call_fns = set()
    for f in flights:
        if isinstance(f, dict) and f.get('flight_number'):
            call_fns.add(f['flight_number'])
    if not call_fns:
        return False

    user_text = ' '.join((m.get('content') or '').lower() for m in history[-15:] if m.get('role') == 'user')
    if 'cheapest' not in user_text or 'economy' not in user_text:
        return False

    flight_re = re.compile(r'\b[A-Z]{3}[0-9]{1,4}\b')
    price_re = re.compile(r'\$([0-9,]+)')

    last_assistant = None
    for m in reversed(history):
        if m.get('role') == 'assistant' and m.get('content'):
            c = m['content']
            if '$' in c and any(fn in c for fn in call_fns):
                last_assistant = c
                break
    if not last_assistant:
        return False

    def block_total(block_text):
        lines = block_text.split('\n')
        total = None
        seg_sum = 0
        has_flight_price = False
        for line in lines:
            prices = [int(x.replace(',', '')) for x in price_re.findall(line)]
            if not prices:
                continue
            m_total = re.search(r'\btotal\b[^$]*\$([0-9,]+)', line, re.I)
            if m_total:
                p = int(m_total.group(1).replace(',', ''))
                total = p if total is None else min(total, p)
                continue
            fls = flight_re.findall(line)
            if not fls:
                continue
            has_flight_price = True
            if len(prices) == 1 and len(fls) > 1:
                seg_sum += prices[0]
            elif len(prices) == len(fls):
                seg_sum += sum(prices)
            else:
                seg_sum += min(prices)
        if total is not None:
            return total
        if has_flight_price:
            return seg_sum
        return None

    def looks_like_itinerary(text):
        return bool(
            re.search(r'\d{4}-\d{2}-\d{2}', text) or
            '→' in text or '->' in text or
            re.search(r'\b\d{1,2}:\d{2}\b', text)
        )

    def is_complete_option(text):
        if re.search(r'(?im)^\s*[\*_#>-]*\s*(option|itinerary|alternative|choice|direct|nonstop|non-stop|one-stop|onestop|connecting|via)\b', text):
            return True
        if re.search(r'\btotal\b', text, re.I) and price_re.search(text):
            return True
        if len(set(flight_re.findall(text))) >= 2:
            return True
        return False

    lines = last_assistant.split('\n')
    raw_blocks = []
    cur = []
    start_re = re.compile(r'^(option|itinerary|alternative|choice|direct|nonstop|non-stop|one-stop|onestop|connecting|via|(?:the\s+)?cheapest)\b', re.I)
    for line in lines:
        stripped = line.strip()
        if not stripped:
            if cur:
                raw_blocks.append('\n'.join(cur))
                cur = []
            continue
        heading = re.sub(r'^[\s\*_#>-]+', '', stripped)
        if start_re.match(heading) or re.match(r'^\d+[\.\)]\s', heading):
            if cur:
                raw_blocks.append('\n'.join(cur))
                cur = []
        cur.append(line)
    if cur:
        raw_blocks.append('\n'.join(cur))

    blocks = []
    i = 0
    while i < len(raw_blocks):
        b = raw_blocks[i]
        if not flight_re.search(b) and i + 1 < len(raw_blocks) and flight_re.search(raw_blocks[i+1]):
            raw_blocks[i+1] = b + '\n' + raw_blocks[i+1]
        else:
            blocks.append(b)
        i += 1

    candidates = []
    for b in blocks:
        b_flights = set(flight_re.findall(b))
        if not b_flights:
            continue
        tot = block_total(b)
        if tot is None:
            continue
        candidates.append((b_flights, tot, b))

    if not candidates:
        return False

    selected = None
    best_overlap = -1
    for b_flights, tot, b in candidates:
        overlap = len(call_fns & b_flights)
        if overlap > best_overlap:
            best_overlap = overlap
            selected = (b_flights, tot, b)
    if selected is None or best_overlap == 0:
        return False

    selected_flights, selected_total, selected_text = selected
    alt_totals = []
    for b_flights, tot, b in candidates:
        if b == selected_text and tot == selected_total:
            alt_totals.append(tot)
        elif is_complete_option(b) or looks_like_itinerary(b):
            alt_totals.append(tot)

    if not alt_totals:
        return False
    cheapest = min(alt_totals)
    return selected_total > cheapest + 0.5
"}]}

{
