      "name": "block_update_flights_for_route_change",
      "code": "def check(call, history):
    import re
    if call.get('name') != 'update_reservation_flights':
        return False
    rid = call.get('arguments', {}).get('reservation_id')
    if not rid:
        return False
    origin = dest = None
    for m in history:
        if m.get('role') == 'tool':
            res = m.get('result')
            if isinstance(res, dict):
                if res.get('reservation_id') == rid or res.get('id') == rid:
                    if res.get('origin'):
                        origin = res.get('origin')
                    if res.get('destination'):
                        dest = res.get('destination')
                    if origin and dest:
                        break
    codes = set()
    for m in history:
        if m.get('role') == 'tool':
            res = m.get('result')
            if isinstance(res, dict):
                for k in ('origin', 'destination'):
                    v = res.get(k)
                    if isinstance(v, str) and len(v) == 3:
                        codes.add(v)
        elif m.get('role') == 'user':
