{"checks":[{"name":"redundant_baggage_update_matching_latest_result","code":"def check(call, history):
    import json
    import re
    if call.get('name') != 'update_reservation_baggages':
        return False
    args = call.get('arguments') or {}
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except Exception:
            return False
    if not isinstance(args, dict):
        return False
    rid = args.get('reservation_id')
    if rid is None or rid == '':
        return False
    try:
        total = int(args.get('total_baggages'))
        nonfree = int(args.get('nonfree_baggages'))
    except Exception:
        return False

    def to_int(v):
        try:
            return int(v)
        except Exception:
            return None

    def extract(d):
        if not isinstance(d, dict):
            return None
        t = d.get('total_baggages')
        n = d.get('nonfree_baggages')
        if t is None:
            t = d.get('total_baggage')
        if n is None:
            n = d.get('nonfree_baggage')
        if t is None or n is None:
            bag = d.get('baggages')
            if not isinstance(bag, dict):
                bag = d.get('baggage')
            if isinstance(bag, dict):
                if t is None:
                    t = bag.get('total_baggages')
                if t is None:
                    t = bag.get('total_baggage')
                if n is None:
                    n = bag.get('nonfree_baggages')
                if n is None:
                    n = bag.get('nonfree_baggage')
        ti = to_int(t)
        ni = to_int(n)
        if ti is None or ni is None:
            return None
        return (ti, ni)

    def own_rid(d):
        if not isinstance(d, dict):
            return None
        for k in ('reservation_id', 'reservationId', 'reservationID'):
            if k in d:
                return str(d.get(k)) == str(rid)
        for k in ('reservation', 'reservation_info'):
            v = d.get(k)
            if isinstance(v, dict):
                for kk in ('reservation_id', 'reservationId', 'reservationID', 'id'):
                    if kk in v:
                        return str(v.get(kk)) == str(rid)
        return None

    def search(obj, ctx=False):
        if isinstance(obj, str):
            s = obj.strip()
            if not s:
                return None
            try:
                parsed = json.loads(s)
                r = search(parsed, ctx)
                if r is not None:
                    return r
            except Exception:
                pass
            if str(rid) in s and ('total_baggages' in s or 'total_baggage' in s):
                mt = re.search(r'(?:total_baggages|total_baggage)[^0-9]*([0-9]+)', s)
                mn = re.search(r'(?:nonfree_baggages|nonfree_baggage)[^0-9]*([0-9]+)', s)
                if mt and mn:
                    return (int(mt.group(1)), int(mn.group(1)))
            return None
        if isinstance(obj, list):
            for item in obj:
                r = search(item, ctx)
                if r is not None:
                    return r
            return None
        if isinstance(obj, dict):
            own = own_rid(obj)
            if own is True:
                ctx2 = True
            elif own is False:
                ctx2 = False
            else:
                ctx2 = ctx
            if ctx2:
                r = extract(obj)
                if r is not None:
                    return r
            for v in obj.values():
                r = search(v, ctx2)
                if r is not None:
                    return r
            return None
        return None

    for m in reversed(history):
        if not isinstance(m, dict):
            continue
        role = m.get('role')
        if role not in ('tool', 'function', 'tool_response'):
            if 'result' not in m and 'content' not in m and 'tool_result' not in m and 'observation' not in m:
                continue
        res = m.get('result')
        if res is None:
            res = m.get('content')
        if res is None:
            res = m.get('tool_result')
        if res is None:
            res = m.get('observation')
        if res is None:
            res = m
        r = search(res, False)
        if r is not None:
            return r == (total, nonfree)
    return False"}]}

{"checks":[{"name":"payment_method_not_in_user_profile","description":"Flags actions that use a payment method not present in the relevant user's profile.","code":"import json

def check(call, history):
    if not isinstance(call, dict):
        return False
    name = call.get('name')
    args = call.get('arguments') or {}
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except Exception:
            return False
    if not isinstance(args, dict):
        return False

    def parse(x):
        if isinstance(x, str):
            try:
                return json.loads(x)
            except Exception:
                return None
        return x

    def payment_ids_from_value(v):
        out = set()
        if isinstance(v, dict):
            if 'payment_id' in v:
                out.add(v.get('payment_id'))
            if 'id' in v and any(k in v for k in ('source', 'brand', 'last_four', 'type', 'card_number', 'gift_card_number', 'payment_id')):
                out.add(v.get('id'))
            method_attrs = {'source', 'brand', 'last_four', 'type', 'card_number', 'gift_card_number', 'payment_id', 'id'}
            if not any(k in v for k in method_attrs):
                for k, val in v.items():
                    out.add(k)
                    out |= payment_ids_from_value(val)
        elif isinstance(v, list):
            for item in v:
                out |= payment_ids_from_value(item)
        elif isinstance(v, str):
            out.add(v)
        return out

    def find_profiles(obj):
        profiles = []
        if isinstance(obj, dict):
            if 'user_id' in obj and 'payment_methods' in obj:
                ids = payment_ids_from_value(obj.get('payment_methods'))
                if ids:
                    profiles.append((obj.get('user_id'), ids))
            for val in obj.values():
                profiles.extend(find_profiles(val))
        elif isinstance(obj, list):
            for val in obj:
                profiles.extend(find_profiles(val))
        return profiles

    all_profiles = []
    for m in reversed(history or []):
        if not isinstance(m, dict) or m.get('role') != 'tool':
            continue
        for key in ('result', 'content', 'output', 'response'):
            if key in m:
                res = parse(m[key])
                if res is not None:
                    all_profiles.extend(find_profiles(res))

    profile_map = {}
    recent_profiles = []
    for uid, ids in all_profiles:
        if uid not in profile_map:
            profile_map[uid] = set()
            recent_profiles.append((uid, profile_map[uid]))
        profile_map[uid].update(ids)

    if name == 'book_reservation':
        target_user = args.get('user_id')
        pms = args.get('payment_methods')
        if pms is None:
            pms = args.get('payment_method')
        if pms is None:
            return False
        to_check = payment_ids_from_value(pms)
        if not to_check:
            return False
    elif name in ('update_reservation_flights', 'update_reservation_baggages'):
        pid = args.get('payment_id')
        if not pid:
            return False
        to_check = {pid}
        target_user = None
        rid = args.get('reservation_id')
        if rid:
            def find_user_for_res(obj):
                if isinstance(obj, dict):
                    if obj.get('reservation_id') == rid and 'user_id' in obj:
                        return obj.get('user_id')
                    for v in obj.values():
                        r = find_user_for_res(v)
                        if r is not None:
                            return r
                elif isinstance(obj, list):
                    for v in obj:
                        r = find_user_for_res(v)
                        if r is not None:
                            return r
                return None
            for m in reversed(history or []):
                if not isinstance(m, dict) or m.get('role') != 'tool':
                    continue
                for key in ('result', 'content', 'output', 'response'):
                    if key in m:
                        res = parse(m[key])
                        if res is not None:
                            u = find_user_for_res(res)
                            if u is not None:
                                target_user = u
                                break
                if target_user is not None:
                    break
    else:
        return False

    if target_user is not None:
        for uid, ids in recent_profiles:
            if uid == target_user:
                return any(pid not in ids for pid in to_check)
        return False
    else:
        if not recent_profiles:
            return False
        if len(recent_profiles) == 1:
            ids = recent_profiles[0][1]
            return any(pid not in ids for pid in to_check)
        ids = recent_profiles[0][1]
        return any(pid not in ids for pid in to_check)
"}]}

{"checks":[{"name":"basic_economy_flight_change","code":"def check(call, history):
