                continue
            plan_parts.append(low)
    user_text = ' '.join(user_parts)
    plan_text = ' '.join(plan_parts)
    intent_text = user_text + ' ' + plan_text

    cancel_forms = ['cancel ', 'cancel.', 'cancel,', 'cancel!', 'cancel?', 'canceling', 'cancelling', 'cancelled', 'canceled', 'to cancel', 'please cancel']
    split_words = ['three', '3', 'multiple', 'several', 'separate', 'split', 'one passenger', 'one-passenger', 'per passenger', 'each passenger', 'individual', 'one at a time']
    book_words = ['book', 'booking', 'reservation', 'reserve', 'rebook', 'rebooking']
    existing_words = ['existing', 'original', 'current', 'old', 'previous', 'reservation', 'booking', 'it']

    def has_any(text, words):
        return any(w in text for w in words)

    def near(text, words_a, words_b, limit=300):
        for a in words_a:
            pos = 0
            while True:
                i = text.find(a, pos)
                if i < 0:
                    break
                start = max(0, i - limit)
                for b in words_b:
                    j = text.find(b, start)
                    if j != -1 and j <= i + limit + len(b):
                        return True
                pos = i + 1
        return False

    if not has_any(intent_text, cancel_forms):
        return False
    if not has_any(intent_text, split_words):
        return False
    if not has_any(intent_text, book_words):
        return False

    if not (near(intent_text, cancel_forms, split_words) or near(intent_text, split_words, cancel_forms)):
        return False
    if not (near(intent_text, cancel_forms, book_words) or near(intent_text, book_words, cancel_forms)):
